//! Wolfram crossover replay for the speaker product path.
//!
//! The fixture (`fixtures/wolfram-golden-v1.json`, generated by
//! `wolfram/crossover_golden.wls` under Wolfram Engine 15.0.0) carries exact
//! first-order crossover transfers and their symbolic frequency derivatives,
//! per audit-sonium-sim-speaker-20260921 (analytic crossover derivatives;
//! absolute error floors near nulls). The replay pins the branch transfers
//! the public product path differentiates, checks the LowPass/HighPass
//! complementarity identity, and uses an absolute floor where the
//! high-pass response approaches its null.

use num_complex::Complex64;
use serde::Deserialize;
use sonium_sim_speaker_modeling::{CrossoverBranch, CrossoverKind};

const FIXTURE: &str = include_str!("../fixtures/wolfram-golden-v1.json");

#[derive(Debug, Deserialize)]
struct Meta {
    engine: String,
    protocol: String,
}

#[derive(Debug, Deserialize, Clone)]
struct ComplexDecimal {
    re: String,
    im: String,
}

#[derive(Debug, Deserialize, Clone)]
struct Case {
    kind: String,
    fc: String,
    gain: String,
    delay_s: String,
    f_hz: String,
    h: ComplexDecimal,
    dhdf: ComplexDecimal,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    meta: Meta,
    cases: Vec<Case>,
}

fn parse(value: &str) -> f64 {
    value.parse().expect("fixture value is a decimal")
}

fn parse_complex(value: &ComplexDecimal) -> Complex64 {
    Complex64::new(parse(&value.re), parse(&value.im))
}

fn parse_fixture() -> Fixture {
    let fixture: Fixture = serde_json::from_str(FIXTURE).expect("valid Wolfram crossover fixture");
    assert!(
        fixture.meta.engine.contains("Wolfram Engine"),
        "fixture must record its Wolfram provenance"
    );
    assert_eq!(fixture.meta.protocol, "audit-oracle-hermetic-v1");
    fixture
}

fn branch(case: &Case) -> CrossoverBranch {
    CrossoverBranch {
        kind: match case.kind.as_str() {
            "LowPass" => CrossoverKind::LowPass,
            "HighPass" => CrossoverKind::HighPass,
            other => panic!("unknown fixture branch kind {other}"),
        },
        corner_frequency_hz: parse(&case.fc),
        gain: parse(&case.gain),
        delay_s: parse(&case.delay_s),
    }
}

#[test]
fn crossover_transfer_matches_wolfram() {
    let fixture = parse_fixture();
    assert!(!fixture.cases.is_empty());
    for case in &fixture.cases {
        let frequency = parse(&case.f_hz);
        let expected = parse_complex(&case.h);
        let actual = branch(case)
            .transfer_at(frequency)
            .expect("fixture branch evaluates");
        let error = (actual - expected).norm();
        // Absolute floor near the high-pass null; relative budget elsewhere.
        let budget = if expected.norm() < 0.05 {
            1e-12
        } else {
            1e-9 * expected.norm()
        };
        assert!(
            error <= budget,
            "{} f={frequency}: Rust {actual:?} vs Wolfram {expected:?} (err {error:e})",
            case.kind
        );
    }
}

#[test]
fn crossover_derivative_matches_wolfram_symbolic() {
    let fixture = parse_fixture();
    for case in &fixture.cases {
        let frequency = parse(&case.f_hz);
        let expected = parse_complex(&case.dhdf);
        // Central finite difference of the branch itself against Wolfram's
        // symbolic D[] derivative: pins the sensitivity, not just the value.
        let step = (frequency * 1e-3).max(1e-6);
        let forward = branch(case)
            .transfer_at(frequency + step)
            .expect("forward branch evaluates");
        let backward = branch(case)
            .transfer_at(frequency - step)
            .expect("backward branch evaluates");
        let actual = (forward - backward) / (2.0 * step);
        let error = (actual - expected).norm();
        let budget = 1e-5 * expected.norm() + 1e-9;
        assert!(
            error <= budget,
            "{} f={frequency}: FD {actual:?} vs Wolfram dH/df {expected:?} (err {error:e})",
            case.kind
        );
    }
}

#[test]
fn crossover_lowpass_highpass_complementarity() {
    // H_LP(f) + H_HP(f) == 1 exactly for matched first-order branches.
    for frequency in [5.0, 100.0, 1_000.0, 8_000.0] {
        let low = CrossoverBranch {
            kind: CrossoverKind::LowPass,
            corner_frequency_hz: 1_000.0,
            gain: 1.0,
            delay_s: 0.0,
        }
        .transfer_at(frequency)
        .expect("low-pass evaluates");
        let high = CrossoverBranch {
            kind: CrossoverKind::HighPass,
            corner_frequency_hz: 1_000.0,
            gain: 1.0,
            delay_s: 0.0,
        }
        .transfer_at(frequency)
        .expect("high-pass evaluates");
        let error = (low + high - Complex64::new(1.0, 0.0)).norm();
        assert!(
            error <= 1e-12,
            "f={frequency}: LP+HP complementarity drifted ({error:e})"
        );
    }
}
